import sys
from rich.traceback import Traceback
from rich.console import Console
from io import StringIO

def test_exception_notes():
    console = Console(file=StringIO())
    try:
        try:
            raise ValueError("Main error")
        except ValueError as e:
            # Python 3.11+ feature
            if hasattr(e, "__notes__"):
                e.add_note("This is a note")
            elif hasattr(e, "add_note"):
                 e.add_note("This is a note")
            else:
                # Fallback for < 3.11 to test the rendering logic if we manually set it
                e.__notes__ = "This is a note"
            raise e
    except Exception:
        console.print(Traceback())

    output = console.file.getvalue()
    print(output)
    assert "Exception notes: This is a note" in output

if __name__ == "__main__":
    try:
        test_exception_notes()
        print("Test passed!")
    except AssertionError:
        print("Test failed!")
        sys.exit(1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        sys.exit(1)

